import loadAsset from './loadAsset';
let countries;
export const load = async () => {
  countries = await loadAsset('countries.json');
  return countries;
};

/**
 * The countries to choose from, by code, in the order of their names.
 */
export function countryOptions(entries, useNativeName) {
  const key = useNativeName ? 'native' : 'name';
  return Object.entries(entries).map(([code, info]) => [code, info[key]]).sort(([, a], [, b]) => a.localeCompare(b)).reduce((options, [code, name]) => {
    options[code] = name;
    return options;
  }, {});
}
export default function getCountries(useNativeName) {
  return countryOptions(countries || {}, useNativeName);
}
export const getEmoji = code => countries?.[code]?.emoji;
flarum.reg.add('fof-discussion-language', 'admin/utils/countries', getCountries);